import (
	"os"
	"runtime/pprof"
)

func fib(n int) int { // intentionally naive: lots of CPU
	if n < 2 {
		return n
	}
	return fib(n-1) + fib(n-2)
}

func main() {
	f, _ := os.Create("profile.out") // file to write the profile to
	defer f.Close()
	pprof.StartCPUProfile(f)          // begin sampling at ~100Hz
	defer pprof.StopCPUProfile()      // flush samples on exit

	_ = fib(35) // do enough work to collect samples
}

