package solution

import "testing"

func TestJoin(t *testing.T) {
	got := Join([]string{"a", "b", "c"}, "-")
	if got != "a-b-c" {
		t.Fatalf("Join = %q want %q", got, "a-b-c")
	}
	if Join(nil, ",") != "" {
		t.Fatalf("empty Join should be empty")
	}
}

func TestJoinAllocs(t *testing.T) {
	parts := []string{"alpha", "beta", "gamma", "delta", "epsilon"}
	allocs := testing.AllocsPerRun(100, func() {
		_ = Join(parts, ", ")
	})
	if allocs > 2 {
		t.Errorf("Join allocates %.0f times; want <= 2", allocs)
	}
}

func BenchmarkJoin(b *testing.B) {
	parts := []string{"alpha", "beta", "gamma", "delta", "epsilon"}
	b.ReportAllocs()
	for i := 0; i < b.N; i++ {
		_ = Join(parts, ", ")
	}
}

