func WithCPUProfile(path string, work func()) error {
	f, err := os.Create(path) // file to receive the profile
	if err != nil {
		return err
	}
	defer f.Close()

	if err := pprof.StartCPUProfile(f); err != nil {
		return err
	}
	defer pprof.StopCPUProfile() // flushes even if work panics

	work() // runs inside the profiling window
	return nil
}
